solution.code:
import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [a, b] = input[0].split(" ").map(Number);

// どちらかが偶数なら積は偶数。積そのものは計算しない
const even = a % 2 === 0 || b % 2 === 0;
console.log(even ? "Even" : "Odd");
